def linear_objective(theta, x, y):
    y_fit = theta[0] + theta[1] * x
    return np.sum((y_fit - y) ** 2)

def exponential_objective(theta, x, y):
    # your code here
    c0, k = theta
    y_fit = c0 * np.exp(-k * x)
    return np.sum((y_fit - y) ** 2)

